# config.py

from pathlib import Path

# Base directory for temporary files generated by the toolkit.
TEMP_DIR = Path("temp")

# Specific subdirectories for different types of output.
SCAN_RESULTS_DIR = TEMP_DIR / "scan_result"
TARGETS_DIR = TEMP_DIR / "targets"
HANDSHAKES_DIR = TEMP_DIR / "handshakes"

# This block ensures that all necessary directories are created automatically
# when the script starts, preventing errors from missing folders.
SCAN_RESULTS_DIR.mkdir(parents=True, exist_ok=True)
TARGETS_DIR.mkdir(parents=True, exist_ok=True)
HANDSHAKES_DIR.mkdir(parents=True, exist_ok=True)